	m.HandleFunc(http.MethodPatch+" "+options.BaseURL+"/v1/vendor-users/{vendor_user_id}", wrapper.UpdateVendorUser)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/vendor-users/{vendor_user_id}/totp-resets", wrapper.ResetVendorUserTotp)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/organisations", wrapper.ListOrganisations)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/organisations", wrapper.CreateOrganisation)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/organisations/{organisation_id}", wrapper.GetOrganisation)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/organisations/{organisation_id}/owner-invitations", wrapper.ListOwnerInvitations)
